import type { JSX, SVGProps } from "react";

export type InfoIconProps = Omit<SVGProps<SVGSVGElement>, "color"> & {
  size?: number;
  color?: string;
  testID?: string;
};

/**
 * Lucide `Info` for the web and for the DOM-based tests. The native twin is
 * `Info.native.tsx`, generated by the official Tamagui v3 command
 * (`npx @tamagui/cli icons add Info`) on top of `react-native-svg`.
 */
export function Info({
  size = 24,
  color = "currentColor",
  testID,
  ...rest
}: InfoIconProps): JSX.Element {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke={color}
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      {...rest}
      aria-hidden="true"
      focusable="false"
      data-testid={testID}
    >
      <circle cx="12" cy="12" r="10" stroke={color} />
      <path d="M12 16v-4" stroke={color} />
      <path d="M12 8h.01" stroke={color} />
    </svg>
  );
}

Info.displayName = "Info";
